if(MOD(HOUR(TIMEDIFF(a.flow_end_time, a.flow_node_time)), 24) = 0,'',CONCAT(MOD(HOUR(TIMEDIFF(a.flow_end_time, a.flow_node_time)), 24),'小时')),
if(MINUTE(TIMEDIFF(a.flow_end_time,a.flow_node_time)) = 0,'',CONCAT(MINUTE(TIMEDIFF(a.flow_end_time,a.flow_node_time)),'分')),
